#!/usr/bin/env python3
"""Persist independent L04 v2 review; do not edit question or bank data."""
import datetime,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from validate import question_hash,CHECK_KEYS
load=lambda p:json.loads((ROOT/p).read_text())
blindpath=ROOT/'audits/blind-answers-W01-L04-v2-independent.json';blind=load(blindpath)
assert blind['complete'] and blind['solvedBeforeAnswerSeen'] and not blind['keyedBatchOpened']
answers={a['questionId']:a for a in blind['answers']};packet={q['id']:q for q in load('audits/blind-W01-L04-v2-revisions.json')['questions']}
batch=load('data/question-batches/W01-L04.json');questions={q['id']:q for q in batch['questions']};summary=load('audits/W01-L04-v2-revision-summary.json');archive={q['id']:q for q in load(summary['archivedV1Path'])['questions']}
assert len(answers)==37 and len(summary['preservedApprovedHashes'])==94
for qid,sha in summary['preservedApprovedHashes'].items():assert question_hash(questions[qid])==sha and questions[qid]==archive[qid]
flags={
'W01-L04-P0144-Q02':'Replace o2 (the code must contain a syntax error) with a plausible verification-versus-validation confusion, such as requiring an implementation bug rather than allowing a faithful implementation of an inadequate physical model. The stem already says a simulation ran and predicted success, so a parsing failure is an implausible cause and can be eliminated without understanding validation. A useful alternative would incorrectly conclude that only code verification failed; avoid a second defensible answer or another categorical unrelated failure.',
'W01-L04-P0160-Q02':'Replace the duplicated automatic-continuation alternatives o2/o3 with distinct plausible parse/runtime outcomes. Both currently assert that adjacency automatically joins the lines and calculates the divisor, testing the same misconception twice. Replace o4 (division by CSV row count), since no count operation supplies that divisor in the code. Better competitors distinguish parse-time SyntaxError from a runtime failure after earlier lines, or a valid but differently interpreted expression. Keep the explicit literal-newline premise and the correct SyntaxError answer unchanged.'
}
now=datetime.datetime.now(datetime.timezone.utc).isoformat();reviewer=blind['reviewerId'];reviews=[]
for qid,a in answers.items():
 q=questions[qid];assert question_hash(q)==a['questionSha256']==packet[qid]['questionSha256'];assert set(q['correctOptionIds'])==set(a['independentAnswerOptionIds']);assert reviewer not in {q['authorId'],*q.get('revisionAuthors',[])}
 checks={k:True for k in CHECK_KEYS}
 if qid in flags:checks['distractors']=False
 reasoning=a['reasoning']+' After the blind answers were frozen, I read the full keyed solution, every option explanation, steps and formula metadata. They agree with the source-derived answer and independently checked execution/calculation. Printed claims, explicitly repaired snippets and generated test values remain distinguished. Source references and exact figure/code details match the inspected pixels.'
 if qid.endswith('P0166-Q07'):reasoning+=' The unusually tricky label is defensible for this explicit variant: it combines whole-array floating inference, integral-valued first-row confusion, and in-place versus rebinding semantics; the version/casting assumptions keep it reproducible rather than platform-ambiguous.'
 reasoning+=' Difficulty and overlap were considered against the item’s actual reasoning: simple naming is easy, conceptual distinctions/mappings and short code/numerical traces are medium. Related questions test distinct source labels, algorithm boundaries, data operations or distance definitions rather than merely changing unmotivated numbers.'
 reviews.append({'id':f'REV-{qid}-v2-independent-interface','questionId':qid,'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':reviewer,'decision':'flagged' if qid in flags else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in q['citations']},'reviewedSlideIds':a['reviewedSlideIds'],'sourceInspectionEvidence':[{'physicalPage':c['physicalPage'],'inspectorIds':[reviewer],'previewSha256':hashlib.sha256((ROOT/f"sources/previews/lectures/page-{c['physicalPage']:04d}.webp").read_bytes()).hexdigest()} for c in q['citations']],'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':True,'checks':checks,'reasoning':reasoning,'findings':[flags[qid]] if qid in flags else [],'reviewType':'independent_blind_revision_review','priorReviewerExposure':False,'priorAuthorExposure':False,'blindAnswersPath':str(blindpath.relative_to(ROOT)),'blindAnswersSha256':hashlib.sha256(blindpath.read_bytes()).hexdigest(),'computationsPath':'audits/W01-L04-v2-independent-computations.json'})
out=ROOT/'data/reviews/W01-L04-v2-independent.json';assert not out.exists();out.write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n')
report={'reviewedAt':now,'reviewed':37,'verified':35,'flagged':2,'answerAgreement':37,'answerCorrectionsRequired':0,'independentBlindReview':True,'sourcePagesInspected':blind['sourcePagesInspected'],'computationGroupsPassed':10,'numpyVersionTested':'2.3.5','priorAcceptedObjectsAndHashesPreserved':94,'reviewPath':str(out.relative_to(ROOT)),'blindAnswersPath':str(blindpath.relative_to(ROOT)),'actionableFlags':flags,'approvedCurrentHashes':{r['questionId']:r['questionSha256'] for r in reviews if r['decision']=='verified'},'nonblockingStyleNotes':['Some inherited English/number joins remain (for example distance6.0, row2, aligning50Hz). A later prose pass must bump versions and rebind approval hashes rather than edit approved objects silently.','P0159-Q04 asks for two uses while one correct option groups confusion matrices and occupancy maps. The select-both instruction and exact two-option answer set are clear; “two groups of uses” would be slightly more precise in a future revision.'],'sourceAndScopeNotes':['This was the reviewer’s first exposure to these questions; blind answers were frozen before keyed batch and previous review access.','The quoted source syntax/name defects are evaluated under explicit literal-code premises, not silently repaired. The generated finite-difference and in-place-array variants are labeled as variants.','No question, source PDF, source-dispute ledger, inspection, original review or canonical bank was changed.']}
(ROOT/'audits/W01-L04-v2-independent-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:report[k] for k in ['reviewed','verified','flagged','answerAgreement','priorAcceptedObjectsAndHashesPreserved']}))
